<script>let timer;document.getElementById('bike_number').addEventListener('input',e=>{clearTimeout(timer);timer=setTimeout(async()=>{let n=e.target.value.trim();if(n.length<3)return;let r=await fetch(@json(url('/bike-intakes/lookup'))+'/'+encodeURIComponent(n));if(!r.ok)return;let b=await r.json();let h=document.getElementById('history');if(b&&b.id){document.getElementById('bike_model').value=b.model||'';document.getElementById('phone').value=b.customer?.phone||'';document.getElementById('customer_name').value=b.customer?.name||'';document.getElementById('address').value=b.customer?.address||'';document.getElementById('nic').value=b.customer?.nic||'';h.textContent=`Existing bike found — ${b.intakes?.length||0} previous intake(s). Details remain editable.`;h.classList.remove('hidden')}else h.classList.add('hidden')},450)});</script></x-layouts::app>
